import itertools


def fmt(minutes):
    h = minutes // 60
    m = minutes % 60
    suffix = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{suffix}"


def main():
    locations = ["Bayview", "Union Square", "Presidio"]

    dist = {
        ("Bayview", "Union Square"): 17,
        ("Bayview", "Presidio"): 31,
        ("Union Square", "Bayview"): 15,
        ("Union Square", "Presidio"): 24,
        ("Presidio", "Bayview"): 31,
        ("Presidio", "Union Square"): 22,
    }
    for a in locations:
        for b in locations:
            if (a, b) not in dist:
                dist[(a, b)] = 0

    friends = [
        {
            "name": "Richard",
            "loc": "Union Square",
            "start": 8 * 60 + 45,
            "end": 13 * 60,
            "min": 120,
        },
        {
            "name": "Charles",
            "loc": "Presidio",
            "start": 9 * 60 + 45,
            "end": 13 * 60,
            "min": 120,
        },
    ]

    start_time = 9 * 60
    start_loc = "Bayview"
    initial_steps = [f"You start at {start_loc} at {fmt(start_time)}."]

    best_score = (0, -start_time)
    best_steps = initial_steps[:]

    def consider(count, finish, steps):
        nonlocal best_score, best_steps
        score = (count, -finish)
        if score > best_score or (score == best_score and steps < best_steps):
            best_score = score
            best_steps = steps

    for r in range(len(friends) + 1):
        for order in itertools.permutations(friends, r):
            def dfs(idx, curr_time, curr_loc, steps):
                if idx == len(order):
                    consider(len(order), curr_time, steps)
                    return

                friend = order[idx]
                travel = dist[(curr_loc, friend["loc"])]
                arrive = curr_time + travel

                earliest_start = max(arrive, friend["start"])
                latest_start = friend["end"] - friend["min"]

                if earliest_start > latest_start:
                    return

                for start in range(earliest_start, latest_start + 1):
                    end = start + friend["min"]
                    next_steps = steps[:]

                    if travel > 0:
                        next_steps.append(
                            f"You travel to {friend['loc']} in {travel} minutes and arrive at {fmt(arrive)}."
                        )

                    if start > arrive:
                        next_steps.append(f"You wait until {fmt(start)}.")

                    next_steps.append(
                        f"You meet {friend['name']} for {friend['min']} minutes from {fmt(start)} to {fmt(end)}."
                    )

                    dfs(idx + 1, end, friend["loc"], next_steps)

            dfs(0, start_time, start_loc, initial_steps)

    print(best_steps)


if __name__ == "__main__":
    main()

